-- Oracle Database DDL Script

-- Drop the objects created by an earlier run (no error on the first run)
BEGIN
    FOR o IN (
        SELECT 'TABLE ' || table_name || ' CASCADE CONSTRAINTS PURGE' AS stmt
          FROM user_tables
         WHERE table_name IN ('JOB_HISTORY', 'EMPLOYEES', 'DEPARTMENTS')
        UNION ALL
        SELECT 'SEQUENCE ' || sequence_name
          FROM user_sequences
         WHERE sequence_name IN ('EMPLOYEE_SEQ', 'DEPARTMENT_SEQ')
    ) LOOP
        EXECUTE IMMEDIATE 'DROP ' || o.stmt;
    END LOOP;
END;
/

-- Departments table
CREATE TABLE departments (
    department_id NUMBER(6) PRIMARY KEY,
    department_name VARCHAR2(30) NOT NULL,
    manager_id NUMBER(6),
    location_id NUMBER(4),
    created_at TIMESTAMP DEFAULT SYSDATE,
    updated_at TIMESTAMP DEFAULT SYSDATE
);

-- Employees table
CREATE TABLE employees (
    employee_id NUMBER(6) PRIMARY KEY,
    first_name VARCHAR2(20),
    last_name VARCHAR2(25) NOT NULL,
    email VARCHAR2(25) NOT NULL UNIQUE,
    phone_number VARCHAR2(20),
    hire_date TIMESTAMP DEFAULT SYSDATE,
    job_id VARCHAR2(10) NOT NULL,
    salary NUMBER(8,2),
    commission_pct NUMBER(2,2),
    manager_id NUMBER(6),
    department_id NUMBER(6),
    created_at TIMESTAMP DEFAULT SYSDATE,
    updated_at TIMESTAMP DEFAULT SYSDATE,
    CONSTRAINT emp_salary_min CHECK (salary > 0),
    CONSTRAINT emp_dept_fk FOREIGN KEY (department_id) REFERENCES departments(department_id),
    CONSTRAINT emp_manager_fk FOREIGN KEY (manager_id) REFERENCES employees(employee_id)
);

-- Job history table
CREATE TABLE job_history (
    employee_id NUMBER(6) NOT NULL,
    start_date TIMESTAMP NOT NULL,
    end_date TIMESTAMP NOT NULL,
    job_id VARCHAR2(10) NOT NULL,
    department_id NUMBER(6),
    created_at TIMESTAMP DEFAULT SYSDATE,
    CONSTRAINT jhist_date_interval CHECK (end_date > start_date),
    CONSTRAINT jhist_emp_fk FOREIGN KEY (employee_id) REFERENCES employees(employee_id),
    CONSTRAINT jhist_dept_fk FOREIGN KEY (department_id) REFERENCES departments(department_id)
);

-- Sequences (Oracle specific)
CREATE SEQUENCE employee_seq
    START WITH 1000
    INCREMENT BY 1
    NOCACHE
    NOCYCLE;

CREATE SEQUENCE department_seq
    START WITH 610
    INCREMENT BY 10
    NOCACHE
    NOCYCLE;

-- Indexes for performance
CREATE INDEX emp_department_ix ON employees (department_id);
CREATE INDEX emp_manager_ix ON employees (manager_id);
CREATE INDEX emp_name_ix ON employees (last_name, first_name);
CREATE INDEX emp_salary_ix ON employees (salary);
CREATE INDEX emp_hire_date_ix ON employees (hire_date);

-- Function-based index (Oracle specific)
CREATE INDEX emp_upper_email_ix ON employees (UPPER(email));

CREATE INDEX emp_job_ix ON employees (job_id);

-- Triggers for audit columns
CREATE OR REPLACE TRIGGER employees_audit_trg
    BEFORE UPDATE ON employees
    FOR EACH ROW
BEGIN
    :NEW.updated_at := SYSDATE;
END;
/

CREATE OR REPLACE TRIGGER departments_audit_trg
    BEFORE UPDATE ON departments
    FOR EACH ROW
BEGIN
    :NEW.updated_at := SYSDATE;
END;
/

-- Sample data: 60 departments, 50 employees
-- The same statements run on Oracle and PostgreSQL (fixed timestamps, so the data is identical).


COMMIT;

exit ;

